async function sendProgress(){const clients=await self.clients.matchAll({type:'window',includeUncontrolled:true});for(const client of clients)client.postMessage({...installProgress});}
async function contentHash(response){const data=await response.clone().arrayBuffer();return [...new Uint8Array(await crypto.subtle.digest('SHA-256',data))].map(v=>v.toString(16).padStart(2,'0')).join('');}
async function verifiedDownload(path,expected,onChunk=()=>{}){
 for(let attempt=0;attempt<3;attempt++){
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),25000);
  try{const url=new URL(path,self.location.href);url.searchParams.set('app-build',CACHE);url.searchParams.set('attempt',String(attempt));const response=await fetch(url,{cache:'reload',credentials:'same-origin',signal:controller.signal});if(!response.ok)throw Error('HTTP '+response.status);
   const chunks=[];let size=0;const reader=response.body?.getReader();if(reader){while(true){const part=await reader.read();if(part.done)break;chunks.push(part.value);size+=part.value.byteLength;onChunk(size);}}else{const bytes=new Uint8Array(await response.arrayBuffer());chunks.push(bytes);size=bytes.length;onChunk(size);}
   const result=new Response(new Blob(chunks),{status:200,headers:response.headers});if(await contentHash(result)!==expected)throw Error('资源校验失败');return result;
  }catch(error){if(attempt===2)throw error;}finally{clearTimeout(timer);}
 }
}
